);
if (stream) {
return new Response(stream, { status: 200 });
}
/*
* For when the generation is "active" during SSR but the
* resumable stream has concluded after reaching this point.
*/
const messages = await getMessagesByChatId({ id: chatId });
const mostRecentMessage = messages.at(-1);
if (!mostRecentMessage || mostRecentMessage.role !== 'assistant') {
return new Response(emptyDataStream, { status: 200 });
}
const messageCreatedAt = new Date(mostRecentMessage.createdAt);
const streamWithMessage = createDataStream({
execute: buffer => {
buffer.writeData({
type: 'append-message',
message: JSON.stringify(mostRecentMessage),
});
},
});
return new Response(streamWithMessage, { status: 200 });
}
```
بعد از پیادهسازی GET handler، میتوانید POST handler را بهروزرسانی کنید تا ساخت استریمهای قابل ادامه دادن را مدیریت کند.

استفاده از toolها در چت بات هوش مصنوعی — مثال

در این مثال، از سه tool استفاده خواهیم کرد:
- `getWeatherInformation`: یک tool سمت سرور که به صورت خودکار اجرا میشود و وضعیت آبوهوای شهر خواسته شده را return میکند
- `askForConfirmation`: یک tool سمت کلاینت نیازمند تعامل با کاربر که از کاربر درخواست تایید دارد
- `getLocation`: یک tool سمت سرور که به صورت خودکار اجرا میشود و یک شهر تصادفی را return میکند
در مسیر `app/api/chat/route.ts`، قطعه کد زیر را قرار دهید:
```js
// npm add @ai-sdk/openai@^1 ai@^4
import { createOpenAI } from '@ai-sdk/openai';
import { streamText } from 'ai';
import { z } from 'zod';
const my_model = createOpenAI({
baseURL: process.env.BASE_URL!,
apiKey: process.env.LIARA_API_KEY!,
});
// Allow streaming responses up to 30 seconds
export const maxDuration = 30;
export async function POST(req: Request) {
const { messages } = await req.json();
const result = streamText({
model: my_model('openai/gpt-4o-mini'),
messages,
tools: {
// server-side tool with execute function:
getWeatherInformation: {
description: 'show the weather in a given city to the user',
parameters: z.object({ city: z.string() }),
execute: async ({}: { city: string }) => {
const weatherOptions = ['sunny', 'cloudy', 'rainy', 'snowy', 'windy'];
return weatherOptions[
Math.floor(Math.random() * weatherOptions.length)
];
},
},
// client-side tool that starts user interaction:
askForConfirmation: {
description: 'Ask the user for confirmation.',
parameters: z.object({
message: z.string().describe('The message to ask for confirmation.'),
}),
},
// client-side tool that is automatically executed on the client:
getLocation: {
description:
'Get the user location. Always ask for confirmation before using this tool.',
parameters: z.object({}),
},
},
});
return result.toDataStreamResponse();
}
```

