Messages: []openai.ChatCompletionMessageParamUnion{
openai.UserMessage("Hello!"),
},
Model: model,
})
if err != nil {
panic(err.Error())
}
fmt.Println("Model Response:", chatCompletion.Choices[0].Message.Content)
}
```

