```php
<?php
require_once __DIR__ . '/vendor/autoload.php';
use Exception;
use MongoDBClient;
$uri = getenv('MONGODB_URI');
$options = [
'connectTimeoutMS' => 5000,
'socketTimeoutMS' => 60000,
