برای استفاده از این قابلیت در دیتابیس MSSQL نیاز به انجام کار خاصی نیست؛ چرا که پکیج `mssql` به صورت خودکار، از این قابلیت، پشتیبانی میکند. صرفاً کافیست تا فیلد `pool` را به شکل زیر، به قطعه کد اتصال به دیتابیس، اضافه کنید:
```js
const sql = require('mssql');
const appPool = new sql.ConnectionPool({
server: process.env.DB_HOST,
port: process.env.DB_PORT,
user: process.env.DB_USER,
password: process.env.DB_PASS,
database: process.env.DB_NAME,
pool: {
min: 10,
max: 100,
acquireTimeoutMillis: 15000,
},
options: {
encrypt: false,
trustServerCertificate: false
}
});
appPool.connect().then(pool => {
console.log(`SERVER: Connected to the db and ${pool.available} connections are available!`);
});
```

