در نهایت میتوانید در پروژهی خود مانند مثال زیر عمل کرده و با استفاده از دسترسی SMTP سرویس ایمیل لیارا،
اقدام به ارسال ایمیلهای تراکنشی کنید:
```go
package main
import (
"fmt"
"log"
"os"
"strconv"
gomail "gopkg.in/mail.v2"
)
func main() {
// Fetch environment variables
host := os.Getenv("MAIL_HOST")
port, err := strconv.Atoi(os.Getenv("MAIL_PORT"))
if err != nil {
panic(err)
}
user := os.Getenv("MAIL_USER")
password := os.Getenv("MAIL_PASSWORD")
from := os.Getenv("MAIL_FROM")
// Define the email recipient, subject, and body
to := "recipient@example.com"
subject := "Test Email"
body := "This is a test email."
// Set up the email message
msg := gomail.NewMessage()
msg.SetHeader("From", from)
msg.SetHeader("To", to)
msg.SetHeader("Subject", subject)
msg.SetHeader("x-liara-tag", "test-tag")
msg.SetBody("text/plain", body)
// Set up the SMTP client
dialer := gomail.NewDialer(host, port, user, password)
dialer.SSL = true // force SSL
// Send the email
err = dialer.DialAndSend(msg)
if err != nil {
log.Fatalf("Failed to send email: %s", err)
} else {
fmt.Println("Email sent successfully!")
}
}
```

