list: {
unsubscribe: {
url: 'http://example.com',
comment: 'Unsubscribe'
},
subscribe: [
'<mailto:admin@example.com?subject=subscribe>',
{
url: 'http://example.com',
comment: 'Subscribe'
}
]
}
};
try {
