using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
class Program
{
static string token = "YOUR-API-TOKEN";
static string sshKey = "your-ssh-key";
static async Task Main(string[] args)
{
using var client = new HttpClient();
var url = "https://iaas-api.liara.ir/vm";
var json = $@"
{{
""name"": ""vm-name"",
""OS"": ""ubuntu-22.04"",
""plan"": ""standard-base-g2"",
""config"": {{
""SSHKeys"": [""{sshKey}""]
}}
}}";
var request = new HttpRequestMessage
{
Method = HttpMethod.Post,
RequestUri = new Uri(url),
Content = new StringContent(json, Encoding.UTF8, "application/json")
};
request.Headers.Add("Authorization", "Bearer " + token);
var response = await client.SendAsync(request);
if (response.IsSuccessStatusCode)
{
var responseString = await response.Content.ReadAsStringAsync();
Console.WriteLine(responseString);
}
else
{
Console.WriteLine($"Error: {response.StatusCode}");
var errorMessage = await response.Content.ReadAsStringAsync();
Console.WriteLine($"Error message: {errorMessage}");
}
}
}
```
> در دستورات و قطعه کدهای فوق، بهجای `YOUR-API-TOKEN`، [توکن API حساب خود](https://docs.liara.ir/references/api/about) و بهجای `your-ssh-key`، کلید SSH خود را وارد کنید.

